return ['domain'=>NULL,'plural-forms'=>'nplurals=3; plural=(n % 10 == 1 && n % 100 != 11) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'bel','project-id-version'=>'Babilim 1.0.0','pot-creation-date'=>'2026-10-31T05:52:59+00:00','po-revision-date'=>'2026-10-31T05:52:59+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Дадае адсутныя пераклады для плагінаў і тэм, ужо ўсталяваных на вашым сайце.','Translations'=>'Пераклады','Babilim Settings'=>'Налады Babilim','Settings'=>'Налады','You are not allowed to do this.'=>'Вам не дазволена гэта рабіць.','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Выберыце менш кампанентаў: не больш за %1$d аперацый за адзін запуск (вы выбралі %2$d).','That component is not installed on this site, so a translation cannot be requested for it.'=>'Гэты кампанент не ўсталяваны на гэтым сайце, таму запытаць для яго пераклад нельга.','Already installed.'=>'Ужо ўсталявана.','Downloaded and installed.'=>'Спампавана і ўсталявана.','Babilim has not been enabled for this site yet.'=>'Babilim для гэтага сайта яшчэ не ўключаны.','No build is available to download for this locale.'=>'Для гэтай лакалі няма зборкі, даступнай для спампоўвання.','Rolled back to the previous build.'=>'Выканана вяртанне да папярэдняй зборкі.','Rolled back and reported.'=>'Адкат выкананы, справаздача адпраўлена.','Rolled back, but the report could not be sent: %s'=>'Адкат выкананы, але справаздачу адправіць не ўдалося: %s','Removed.'=>'Выдалена.','Translation requested.'=>'Пераклад запрошаны.','This component was already uploaded. Babilim is checking it now.'=>'Гэты кампанент ужо быў загружаны. Babilim зараз правярае яго.','Upload cancelled.'=>'Загрузка скасавана.','Upload complete — translation requested.'=>'Загрузка завершана — пераклад запрошаны.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Гэты кампанент не паказвае нумар версіі, таму запытаць для яго пераклад нельга.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Нумар версіі гэтага кампанента даўжэйшы за %d сімвалаў, чаго Babilim апрацаваць не можа, таму запытаць для яго пераклад нельга.','A translation cannot be requested for that locale on this site right now.'=>'Зараз запытаць пераклад для гэтай лакалі на гэтым сайце немагчыма.','Thank you. Your report was sent.'=>'Дзякуй. Вашу справаздачу адпраўлена.','This report does not name a valid plugin or theme and locale.'=>'У гэтай справаздачы не паказаны сапраўдны плагін або тэма і лакаль.','Please choose a category for this report.'=>'Выберыце катэгорыю для гэтай справаздачы.','This report is missing a valid build to report against.'=>'У гэтым справаздачы адсутнічае сапраўдная зборка, да якой яна адносіцца.','This build is not one this site currently knows about for this component/locale.'=>'Гэтая зборка не з\'яўляецца той, пра якую гэты сайт зараз ведае для гэтага кампанента і лакалі.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Поле "%1$s" занадта доўгае: у ім %2$d сімвалаў, а ліміт — %3$d. Нічога не адпраўлена; скараціце яго і паспрабуйце яшчэ раз.','Original string'=>'Зыходны радок','String context'=>'Кантэкст радка','Current translation'=>'Бягучы пераклад','Suggested translation'=>'Прапанаваны пераклад','Note (optional)'=>'Заўвага (неабавязкова)','Where you saw this (optional)'=>'Дзе вы гэта ўбачылі (неабавязкова)','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Сінхранізацыя Babilim часова затрымана сэрвісам (абмежаванне частаты); яна паспрабуе яшчэ раз пасля %s.','That is not a valid WordPress locale code. Nothing was saved.'=>'Гэта не сапраўдны код лакалі WordPress. Нічога не захавана.','Settings saved.'=>'Налады захаваны.','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Калі гэта ўключана, пры выдаленні таксама будзе сцерта ідэнтычнасць гэтага сайта. Платную ліцэнзію, прывязаную да гэтага сайта, пасля гэтага нельга будзе аднавіць аўтаматычна; каб вярнуць яе, трэба будзе звярнуцца ў падтрымку Babilim па адрасе %s.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim наладжаны так, каб сцерці ідэнтычнасць гэтага сайта пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтага сайта, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %s. Каб захаваць ідэнтычнасць, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim і дэактывуйце яшчэ раз. Усё роўна дэактываваць?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d сайт у гэтай сетцы наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтага сайта, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %2$s. Каб захаваць ідэнтычнасць, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim гэтага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?' . "\0" . '%1$d сайты ў гэтай сетцы наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтых сайтаў, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %2$s. Каб захаваць ідэнтычнасці, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim кожнага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?' . "\0" . '%1$d сайтаў у гэтай сетцы наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да гэтых сайтаў, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %2$s. Каб захаваць ідэнтычнасці, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim кожнага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'У гэтай сетцы занадта шмат сайтаў, каб правяраць іх па адным, і некаторыя з іх могуць быць наладжаны так, каб сцерці ідэнтычнасць Babilim пры выдаленні плагіна. Платную ліцэнзію, прывязаную да такога сайта, тады нельга будзе аднавіць аўтаматычна; трэба будзе звярнуцца ў падтрымку Babilim па адрасе %s. Каб захаваць ідэнтычнасці, націсніце «Скасаваць», зніміце сцяжок «Выдаліць усе даныя Babilim пры выдаленні» ў Налады Babilim кожнага сайта і дэактывуйце яшчэ раз. Усё роўна дэактываваць?','Open Babilim settings'=>'Адкрыць налады Babilim','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim не здолеў праверыць гэты сайт, таму нічога не спампоўваецца і не ўсталёўваецца.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Сэрвіс не здолеў звязацца з вашым сайтам. Магчыма, брандмаўэр, плагін бяспекі або правіла хостынгу блакуе запыт; калі ласка, дазвольце запыты да /wp-json/babilim/v1/challenge.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Ваш сайт адказваў занадта доўга. Паспрабуйце пазней і праверце, ці не занадта павольны або перагружаны ваш хостынг.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Ваш сайт адказаў, але не тым, чаго чакалася. Магчыма, REST API перапісваецца іншым плагінам або гэты эндпоінт кэшуецца; калі ласка, выключыце /wp-json/babilim/v1/challenge з кэшавання і перапісвання.','Please check that your site can be reached from the internet, then try again.'=>'Праверце, ці даступны ваш сайт з інтэрнэту, і паспрабуйце яшчэ раз.','Re-verify'=>'Праверыць паўторна','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Гэты сайт перавышае памер, які сэрвіс прымае за адну сінхранізацыю, таму некаторыя элементы прапушчаны: кампанентаў — %1$d, лакалей — %2$d.','This site is verified.'=>'Гэты сайт правераны.','Registration restarted.'=>'Рэгістрацыю перазапушчана.','Sync complete.'=>'Сінхранізацыя завершана.','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilim уключае і правярае гэты сайт… Абнавіце старонку або дачакайцеся завяршэння запланаванай праверкі.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilim не здолеў завяршыць уключэнне (%1$s): %2$s','A host that serves only one PHP request at a time cannot complete this step.'=>'Хостынг, які апрацоўвае толькі адзін запыт PHP за раз, не можа выканаць гэты крок.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim уключаны: сайт правераны, знойдзены %d кампанент.' . "\0" . 'Babilim уключаны: сайт правераны, знойдзена %d кампаненты.' . "\0" . 'Babilim уключаны: сайт правераны, знойдзена %d кампанентаў.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim выключаны. Больш нічога не адпраўляецца; ужо ўсталяваныя пераклады працягваюць працаваць.','Supplementary translation index rebuilt.'=>'Дадатковы індэкс перакладаў адноўлены.','Sweep complete: %d file deleted.'=>'Ачыстка завершана: выдалены %d файл.' . "\0" . 'Ачыстка завершана: выдалена %d файлы.' . "\0" . 'Ачыстка завершана: выдалена %d файлаў.','Removed %d installed component.'=>'Выдалены %d усталяваны кампанент.' . "\0" . 'Выдалена %d усталяваныя кампаненты.' . "\0" . 'Выдалена %d усталяваных кампанентаў.','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Аўтаматычныя ўсталёўкі зараз выключаны; уключыце іх зноў у Налады, калі трэба.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim знаходзіць на гэтым сайце плагіны і тэмы, для якіх няма перакладу на вашу мову, і ўсталёўвае для кожнага пераклад.','Languages found on this site: %s.'=>'Мовы, знойдзеныя на гэтым сайце: %s.','Available translations can be installed with one click, and missing ones can be requested. After that, new translations and updates are installed automatically (on the free plan, only for plugins and themes that already use a free slot).'=>'Даступныя пераклады можна ўсталяваць адным клікам, а адсутныя — запытаць. Пасля гэтага новыя пераклады і абнаўленні ўсталёўваюцца аўтаматычна (на бясплатным плане — толькі для плагінаў і тэм, якія ўжо займаюць вольны слот).','The free plan covers a limited number of plugins and themes; your exact quota is shown in Settings after you enable Babilim.'=>'Бясплатны план пакрывае абмежаваную колькасць плагінаў і тэм; ваша дакладная квота паказана ў раздзеле «Налады» пасля таго, як вы ўключыце Babilim.','What is sent when you enable Babilim'=>'Што адпраўляецца, калі вы ўключаеце Babilim','Enabling…'=>'Уключэнне…','Enable Babilim'=>'Уключыць Babilim','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Націскаючы «Уключыць», вы згаджаецеся адправіць пералічаныя вышэй звесткі ў Babilim.','Check again now'=>'Праверыць яшчэ раз зараз','Babilim installed %d translation automatically since your last visit.'=>'Babilim аўтаматычна ўсталяваў %d пераклад пасля вашага апошняга наведвання.' . "\0" . 'Babilim аўтаматычна ўсталяваў %d пераклады пасля вашага апошняга наведвання.' . "\0" . 'Babilim аўтаматычна ўсталяваў %d перакладаў пасля вашага апошняга наведвання.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilim уключае і правярае гэты сайт… (апошняя спроба: %s)','Check again'=>'Праверыць зноў','No components synced yet.'=>'Кампаненты яшчэ не сінхранізаваны.','%d succeeded'=>'паспяхова: %d' . "\0" . 'паспяхова: %d' . "\0" . 'паспяхова: %d','%d skipped'=>'прапушчана: %d' . "\0" . 'прапушчана: %d' . "\0" . 'прапушчана: %d','%d failed'=>'з памылкай: %d' . "\0" . 'з памылкай: %d' . "\0" . 'з памылкай: %d','%d not yet tried'=>'яшчэ не спрабавана: %d' . "\0" . 'яшчэ не спрабавана: %d' . "\0" . 'яшчэ не спрабавана: %d','%1$s nothing to do.'=>'%1$s nothing to do.','%1$s %2$s.'=>'%1$s %2$s.','Bulk download:'=>'Масавае спампоўванне:','Bulk update:'=>'Масавае абнаўленне:','Bulk request:'=>'Масавы запыт:','per day'=>'у дзень','Wrong meaning'=>'Няправільнае значэнне','Wrong term'=>'Няправільны тэрмін','Broken placeholder'=>'Пашкоджаны запаўняльнік','Wrong for this context'=>'Няправільна для гэтага кантэксту','Wrong plural form'=>'Няправільная форма множнага ліку','Negation reversed'=>'Адмаўленне перайначана','Translation does not load'=>'Пераклад не загружаецца','problem report categoryOther'=>'Іншае','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','Continuing…'=>'Працягваем…','Continue next batch (%d left)'=>'Працягнуць наступную партыю (засталося: %d)','Search components'=>'Пошук кампанентаў','These are the languages this site uses. You can change them in %s.'=>'Гэта мовы, якія выкарыстоўвае гэты сайт. Вы можаце змяніць іх у %s.','Upload this component?'=>'Загрузіць гэты кампанент?','There is no upload waiting for confirmation.'=>'Няма запампоўкі, якая чакае пацвярджэння.','Back'=>'Назад','To translate this component, Babilim needs its source.'=>'Каб перакласці гэты кампанент, Babilim патрэбна яго крыніца.','The entire plugin or theme directory of %1$s (version %2$s) will be uploaded to Babilim.'=>'Уся дырэкторыя плагіна або тэмы %1$s (версія %2$s) будзе запампавана ў Babilim.','If that directory contains keys, logs or customer data, they will be uploaded too. The service removes common sensitive files (configuration, environment, database dumps, logs, keys) but cannot guarantee it finds everything.'=>'Калі гэтая дырэкторыя змяшчае ключы, журналы або даныя кліентаў, яны таксама будуць запампаваны. Сервіс выдаляе распаўсюджаныя канфідэнцыйныя файлы (канфігурацыю, асяроддзе, дампы базы даных, журналы, ключы), але не можа гарантаваць, што знойдзе ўсё.','The upload is kept until you ask Babilim to delete it.'=>'Запампаваныя даныя захоўваюцца, пакуль вы не папросіце Babilim выдаліць іх.','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Яны захоўваюцца хостынг-правайдарам сервіса і апрацоўваюцца мадэлямі ШІ для стварэння перакладу.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Зыходны тэкст і створаныя на яго аснове пераклады будуць перададзены іншым сайтам, якія ўсталююць тую ж версію.','By continuing you confirm that you have the right to upload this component.'=>'Працягваючы, вы пацвярджаеце, што маеце права загрузіць гэты кампанент.','Upload and request'=>'Запампаваць і даслаць запыт','Uploading…'=>'Запампоўка…','Cancel'=>'Скасаваць','Uploading'=>'Запампоўка','There is no upload in progress.'=>'Запампоўка не выконваецца.','Uploading part %1$d of %2$d…'=>'Запампоўка часткі %1$d з %2$d…','Continue'=>'Працягнуць','Confirm'=>'Пацвердзіць','Remove'=>'Выдаліць','Roll back'=>'Адкаціць','Nothing to confirm.'=>'Няма чаго пацвярджаць.','Choose a language'=>'Выберыце мову','Roll back and report'=>'Адкаціць і паведаміць','Report a problem'=>'Паведаміць пра праблему','Nothing to choose.'=>'Няма з чаго выбіраць.','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Выберыце мову.','Supplementary translations'=>'Дадатковыя пераклады','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Уласны ўклад кожнага кампанента ў агульнае дапаўненне да дамена па змаўчанні для кожнай лакалі.','Component'=>'Кампанент','Language'=>'Мова','Included in index'=>'Уключана ў індэкс','Entries'=>'Запісы','Conflicting keys'=>'Канфліктуючыя ключы','Yes'=>'Так','No — component inactive'=>'Не — кампанент неактыўны','No — installed version differs from the active one'=>'Не — усталяваная версія адрозніваецца ад актыўнай','No — component removed'=>'Не — кампанент выдалены','No'=>'Не','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Гэта можа зрабіць толькі адміністратар сеткі, бо змяняюцца файлы перакладу, агульныя для ўсіх сайтаў гэтай сеткі.','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim не здолеў завяршыць праверку гэтага сайта (сервіс не змог звязацца з ім у адказ). Рэгістрацыя прыпынена.','This site already has an active registration that can no longer be recovered automatically.'=>'Гэты сайт ужо мае актыўную рэгістрацыю, якую больш нельга аднавіць аўтаматычна.','Restart registration'=>'Пачаць рэгістрацыю нанова','Babilim settings'=>'Налады Babilim','General'=>'Агульныя','Advanced'=>'Дадатковыя','Languages'=>'Мовы','Automatic installs'=>'Аўтаматычныя ўсталёўкі','Install available translations automatically'=>'Аўтаматычна ўсталёўваць даступныя пераклады','On the free plan, only components that already use one of your free slots are installed automatically, so no new slot is taken.'=>'У бясплатным плане аўтаматычна ўсталёўваюцца толькі кампаненты, якія ўжо выкарыстоўваюць адзін з вашых бясплатных слотаў, таму новы слот не займаецца.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Гэты сайт уваходзіць у сетку multisite, якая не ўсталёўвае новыя пераклады аўтаматычна. Ужо ўсталяваныя пераклады па-ранейшаму абнаўляюцца.','Custom overrides'=>'Уласныя перавызначэнні','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Захоўваць мае ўласныя перавызначэнні перакладаў пры поўным выдаленні даных або выдаленні гэтага плагіна.','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Файлы перакладу, якія вы змяшчаеце ў %s, заўсёды маюць прыярытэт над файламі Babilim. Яны захоўваюцца, пакуль вы не зніміце гэты сцяжок.','Uninstall'=>'Выдаленне','Delete all Babilim data on uninstall'=>'Выдаліць усе даныя Babilim пры выдаленні','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Па змаўчанні выключана: пры выдаленні плагіна ідэнтычнасць гэтага сайта захоўваецца, каб яе можна было паўторна выкарыстаць пры пераўсталёўцы.','Account'=>'Уліковы запіс','Save changes'=>'Захаваць змены','Disable Babilim'=>'Выключыць Babilim','Installed translations are kept, but no further checks or downloads will run.'=>'Усталяваныя пераклады захоўваюцца, але далейшыя праверкі і спампоўванні выконвацца не будуць.','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Выключыць Babilim? Усталяваныя пераклады захоўваюцца, але далейшыя праверкі і загрузкі не будуць выконвацца.','This site is not registered with Babilim yet.'=>'Гэты сайт яшчэ не зарэгістраваны ў Babilim.','This site is already licensed. Reload the page.'=>'Гэты сайт ужо мае ліцэнзію. Перазагрузіце старонку.','Checkout is not available for this site right now.'=>'Афармленне заказу для гэтага сайта цяпер недаступнае.','Could not start checkout: %s'=>'Не атрымалася пачаць афармленне заказу: %s','Babilim is not enabled.'=>'Babilim не ўключаны.','Not registered yet'=>'Яшчэ не зарэгістравана','Not verified'=>'Не правераны','Verified'=>'Пацверджана','Status'=>'Стан','Licensed'=>'Ёсць ліцэнзія','Partner'=>'Партнёр','Free'=>'Бясплатна','License'=>'Ліцэнзія','Upgrade this site'=>'Палепшыць план гэтага сайта','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Аднаразовая пакупка для гэтага сайта: %1$s %2$s. Уключае ўсе будучыя абнаўленні перакладаў. Аплата апрацоўваецца праз Paddle у новай укладцы.','This issues a new restore code and the previous one stops working. Continue?'=>'Будзе выдадзены новы код аднаўлення, а папярэдні перастане працаваць. Працягнуць?','Show a new restore code'=>'Паказаць новы код аднаўлення','rc_…'=>'rc_…','Restore code'=>'Код аднаўлення','Restore purchase'=>'Аднавіць пакупку','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Раней купілі ліцэнзію для гэтага дамена? Увядзіце код аднаўлення, атрыманы пры афармленні заказу.','That does not look like a restore code.'=>'Гэта не падобна на код аднаўлення.','This restore code was not recognised for this site.'=>'Гэты код аднаўлення не распазнаны для гэтага сайта.','Too many attempts. Try again tomorrow.'=>'Занадта шмат спроб. Паспрабуйце зноў заўтра.','This site must be verified first.'=>'Спачатку гэты сайт трэба пацвердзіць.','Could not restore the purchase: %s'=>'Не ўдалося аднавіць пакупку: %s','Purchase restored. This site is now licensed.'=>'Пакупка адноўлена. Цяпер гэты сайт мае ліцэнзію.','This site has no purchase to show a code for.'=>'Для гэтага сайта няма пакупкі, для якой можна паказаць код.','Could not show a new restore code: %s'=>'Не ўдалося паказаць новы код аднаўлення: %s','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Ваш новы код аднаўлення: %s. Захоўвайце яго ў надзейным месцы — папярэдні код больш не працуе.','What is sent when Babilim checks this site'=>'Што адпраўляецца, калі Babilim правярае гэты сайт','(detected)'=>'(выяўлена)','No language is managed yet.'=>'Ніводная мова яшчэ не кіруецца.','Babilim adds translations for every language checked here.'=>'Babilim дадае пераклады для кожнай мовы, адзначанай тут.','Add another language'=>'Дадаць яшчэ адну мову','Choose a language…'=>'Выберыце мову…','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'Не ўдалося загрузіць поўны спіс лакаляў WordPress.org з сервісу, таму цяпер нельга дадаць іншую мову.','Theme'=>'Тэма','Plugin'=>'Плагін','Free quota'=>'Бясплатная квота','Downloads: %1$d/%2$d (%3$s)'=>'Загрузкі: %1$d/%2$d (%3$s)','Supplementary translation index'=>'Індэкс дадатковых перакладаў','Built'=>'Створана','Included'=>'Уключана','Excluded'=>'Выключана','Already in WordPress core'=>'Ужо ў ядры WordPress','Supplementary translation maintenance'=>'Абслугоўванне дадатковых перакладаў','Maintenance status is not available right now.'=>'Стан абслугоўвання цяпер недаступны.','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Ачыстка была прыпынена %1$s: %2$s. Нічога не было выдалена.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Апошняя ачыстка %1$s: %2$d нядаўна пазначана, %3$d файл(аў) выдалена, %4$d запіс(аў) выдалена.','No cleanup has run yet.'=>'Ачыстка яшчэ не выконвалася.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Запіс у індэкс перакладаў канфліктаваў з іншым запытам %1$s (%2$s) і не быў ужыты; захавана апошняя версія.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Запіс у індэкс перакладаў %1$s (%2$s) не ўдалося завяршыць, і ён не быў ужыты (%3$s).','Maintenance'=>'Абслугоўванне','Rebuild index now'=>'Перабудаваць індэкс зараз','Sweep now'=>'Ачысціць зараз','Danger zone'=>'Небяспечная зона','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Выдаляе кожны моўны файл, які Babilim усталяваў для кожнага плагіна і кожнай тэмы на гэтым сайце.','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Выдаліць усё, што ўсталяваў Babilim? Гэта выдаліць кожны моўны файл, які ён усталяваў для кожнага плагіна і кожнай тэмы на гэтым сайце.','Remove everything Babilim installed'=>'Выдаліць усё, што ўсталяваў Babilim','This string is too long to be sent as a report, so no report form is offered for it.'=>'Гэты радок занадта доўгі, каб адправіць яго ў справаздачы, таму форма справаздачы для яго не прапануецца.','Category'=>'Катэгорыя','Choose a category…'=>'Выберыце катэгорыю…','Roll back and send report'=>'Адкаціць і адправіць справаздачу','Send report'=>'Адправіць справаздачу','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Частка тэксту гэтага кампанента жорстка закадзіравана яго аўтарам і не можа быць перакладзена моўным пакетам.','WordPress.org'=>'WordPress.org','Bundled with the theme'=>'Пастаўляецца разам з тэмай','Bundled with the plugin'=>'Пастаўляецца разам з плагінам','Upload was not accepted'=>'Запампоўка не прынята','Upload expired before it finished'=>'Тэрмін запампоўкі скончыўся да яе завяршэння','No translation'=>'Няма перакладу','Upload in progress — continue or cancel'=>'Запампоўка выконваецца — працягнуць або скасаваць','Scheduled, waiting to be processed'=>'Запланавана, чакае апрацоўкі','Translating…'=>'Пераклад…','Translation failed'=>'Не ўдалося перакласці','Free quota used'=>'Бясплатная квота выкарыстана','Needs a paid license'=>'Патрэбна платная ліцэнзія','Not supported'=>'Не падтрымліваецца','Status unknown'=>'Стан невядомы','translation statusInstalled'=>'Усталявана','Update available'=>'Даступна абнаўленне','Removed after a failed integrity check'=>'Выдалена пасля няўдалай праверкі цэласнасці','Installed · built for %s, new version scheduled'=>'Усталявана · створана для %s, новая версія запланавана','Installed · built for a different version, new version scheduled'=>'Усталявана · створана для іншай версіі, новая версія запланавана','Installed · built for %s, translating the new version…'=>'Усталявана · створана для %s, перакладаецца новая версія…','Installed · built for a different version, translating the new version…'=>'Усталявана · створана для іншай версіі, перакладаецца новая версія…','Installed · built for %1$s, this site has %2$s'=>'Усталявана · створана для %1$s, на гэтым сайце %2$s','Installed · built for %s'=>'Усталявана · створана для %s','Installed · built for a different version'=>'Усталявана · створана для іншай версіі','Installed · built for %s, new version failed'=>'Усталявана · створана для %s, збой пры падрыхтоўцы новай версіі','Installed · built for a different version, new version failed'=>'Усталявана · створана для іншай версіі, збой пры падрыхтоўцы новай версіі','Installed · built for %s, new version needs a paid license'=>'Усталявана · зборка для %s, новая версія патрабуе платную ліцэнзію','Installed · built for a different version, new version needs a paid license'=>'Усталявана · зборка для іншай версіі, новая версія патрабуе платную ліцэнзію','Installed · built for %s, free quota used'=>'Усталявана · створана для %s, бясплатная квота выкарыстана','Installed · built for a different version, free quota used'=>'Усталявана · створана для іншай версіі, бясплатная квота выкарыстана','translation statusAvailable'=>'Даступна','Installed · %s'=>'Усталявана · %s','Available · %s'=>'Даступна · %s','Update'=>'Абнавіць','Download'=>'Спампаваць','Updating…'=>'Абнаўленне…','Downloading…'=>'Спампоўванне…','Retry request'=>'Паўтарыць запыт','Request newer translation'=>'Запытаць новы пераклад','Request translation'=>'Запытаць пераклад','Requesting…'=>'Запыт…','Requesting a translation uses one of your free slots, unless this component already uses one. A failed translation does not give the slot back.'=>'Запыт перакладу выкарыстоўвае адзін з вашых бясплатных слотаў, калі гэты кампанент ужо не выкарыстоўвае адзін з іх. Няўдалы пераклад слот не вяртае.','If this component does not use one of your free slots yet, requesting a translation uses one. A failed translation does not give the slot back. Continue?'=>'Калі гэты кампанент яшчэ не выкарыстоўвае ніводнага з вашых бясплатных слотаў, запыт перакладу выкарыстае адзін. Няўдалы пераклад слот не вяртае. Працягнуць?','No plugins or themes found.'=>'Убудовы або тэмы не знойдзены.','Clear filters'=>'Ачысціць фільтры','No components match these filters. %s'=>'Ніводны кампанент не адпавядае гэтым фільтрам. %s','Select all'=>'Выбраць усё','All'=>'Усе','Available'=>'Даступныя','Updates'=>'Абнаўленні','Requestable'=>'Можна запытаць','Installed'=>'Усталяваныя','Plugins'=>'Убудовы','Themes'=>'Тэмы','All languages'=>'Усе мовы','%d to install'=>'%d для ўсталявання' . "\0" . '%d для ўсталявання' . "\0" . '%d для ўсталявання','Language:'=>'Мова:','Bulk actions apply to every matching language of each selected component.'=>'Масавыя дзеянні ўжываюцца да кожнай адпаведнай мовы кожнага абранага кампанента.','Bulk actions apply only to the selected language of each selected component.'=>'Масавыя дзеянні ўжываюцца толькі да абранай мовы кожнага абранага кампанента.','Version %s'=>'Версія %s','Theme · %s'=>'Тэма · %s','Plugin · %s'=>'Убудова · %s','Remove the %2$s translation of %1$s from this site?'=>'Выдаліць з гэтага сайта пераклад %1$s на мову %2$s?','Roll back the %2$s translation of %1$s to the previous build?'=>'Вярнуць пераклад %2$s для %1$s да папярэдняй зборкі?','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','The registration challenge is not in the expected form.'=>'Выклік рэгістрацыі мае неčаканую форму.','That is not a valid build identifier.'=>'Гэта не з\'яўляецца дапушчальным ідэнтыфікатарам зборкі.','Refusing to write outside the Babilim language-file directory.'=>'Адмова ад запісу па-за каталогам моўных файлаў Babilim.','Could not write the downloaded package to disk.'=>'Не атрымалася запісаць спампаваны пакет на дыск.','Unexpected HTTP %d response.'=>'Нечаканы HTTP-адказ %d.','This site\'s URL, so the service can verify you own it.'=>'URL гэтага сайта, каб сэрвіс мог пацвердзіць, што ён належыць вам.','Your WordPress version, to serve compatible translation files.'=>'Ваша версія WordPress, каб прадастаўляць сумяшчальныя файлы перакладу.','Your PHP version, for compatibility.'=>'Ваша версія PHP, для праверкі сумяшчальнасці.','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Версія самога гэтага плагіна, каб сэрвіс мог параіць абнавіць яго, калі яна занадта старая для сувязі.','This site\'s configured locale.'=>'Наладжаная лакаль гэтага сайта.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Кожная лакаль, што выкарыстоўваецца на гэтым сайце (лакаль сайта, усталяваныя моўныя пакеты, лакалі карыстальнікаў і любыя, што вы дадасце ўручную). Ніводная лакаль не разглядаецца інакш за іншую.','(a public key generated for this site)'=>'(публічны ключ, створаны для гэтага сайта)','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Публічны ключ усталёўкі гэтага сайта, які выкарыстоўваецца для пацвярджэння, што запыты сапраўды паходзяць з гэтага сайта. Адпраўляецца толькі публічная частка.','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Кожны ўсталяваны плагін/тэма: яго slug, версія, тэкставы дамен(ы), ці ёсць ён у спісе WordPress.org, ягоныя ўласныя ўбудаваныя лакалі і лакалі, для якіх вы ўжо ўсталявалі пераклад Babilim.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: that component\'s entire directory, as a zip.'=>'Толькі калі вы пацвярджаеце запампоўку плагіна або тэмы, якіх няма ў WordPress.org: увесь каталог гэтага кампанента ў выглядзе zip.','(generic codes and coordinates only)'=>'(толькі агульныя коды і каардынаты)','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Да 20 дыягнастычных падзей у чаканні (напр., файл, які не прайшоў праверку цэласнасці), кожная — толькі код, кампанент і лакаль, без якога-небудзь змесціва радкоў або перакладзенага тэксту.','Unsafe locale: %s'=>'Небяспечная лакаль: %s','Manifest unavailable: %s'=>'Маніфест недаступны: %s','Could not determine active components; the existing merged index was left unchanged.'=>'Не атрымалася вызначыць актыўныя кампаненты; існуючы аб’яднаны індэкс не зменены.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Не ўдалося вызначыць усталяваныя плагіны/тэмы; ачыстка прапушчана, нічога не выдалена.','Sweep aborted without orphaning anything: %s.'=>'Ачыстка спынена без пазначэння асірацелых запісаў: %s.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Ачыстка выканана, але частку яе змен не ўдалося запісаць у індэкс перакладаў; наступная ачыстка паўторыць спробу.','component kind in the sweep brake messagetheme'=>'тэма','component kind in the sweep brake messageplugin'=>'плагін','it would orphan every managed %1$s component (%2$d of %2$d)'=>'гэта зробіць асірацелым кожны кіраваны кампанент тыпу %1$s (%2$d з %2$d)','it would orphan %1$d of %2$d managed components (more than half)'=>'гэта зробіць асірацелымі %1$d з %2$d кіраваных кампанентаў (больш за палову)','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Аб’яднаны індэкс для \'%s\' перабудаваны, але індэкс перакладаў не змог яго запісаць; наступная перабудова паўторыць спробу.','Could not write the staged merged index.'=>'Не ўдалося запісаць падрыхтаваны аб\'яднаны індэкс.','Re-parsed entry count did not match the built index.'=>'Колькасць запісаў пасля паўторнага разбору не супала з пабудаваным індэксам.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Не ўдалося перанесці аб\'яднаны індэкс для \'%s\' на месца; папярэдні індэкс (калі быў) выдалены, каб не заставацца напалову абноўленым. Дапаўненне да дамена па змаўчанні для гэтай лакалі не выдаецца да наступнай паспяховай пабудовы.','Could not open zip: %s'=>'Не атрымалася адкрыць zip: %s','Zip has no manifest.json.'=>'У zip няма manifest.json.','manifest.json in the zip is not valid JSON.'=>'manifest.json у zip не з\'яўляецца дапушчальным JSON.','manifest.json\'s \'%s\' does not match the expected value.'=>'Поле \'%s\' у manifest.json не адпавядае чаканаму значэнню.','Another installation is running; try again in a moment.'=>'Выконваецца іншая ўсталёўка; паўтарыце спробу праз момант.','Not a valid server_build_id: %s'=>'Недапушчальны server_build_id: %s','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Тып \'%1$s\' у маніфесце пакета не адпавядае запытанаму тыпу \'%2$s\'.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Тэкставы дамен пакета \'%1$s\' не адпавядае копіі кампанента на гэтым сайце (\'%2$s\'), таму пакет не ўсталяваны.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Зададзены дамен \'%1$s\' не адпавядае ні ўласнаму slug маніфеста пакета \'%2$s\', ні яго text_domain \'%3$s\'.','Unsafe slug: %s'=>'Небяспечны slug: %s','Unsafe text_domain: %s'=>'Небяспечны text_domain: %s','The package has no %s for its own text domain.'=>'У пакеце няма %s для ўласнага тэкставага дамена.','manifest.json is missing or has an invalid \'%s\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'%s\'.','manifest.json is missing or has an invalid \'entries\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'entries\'.','manifest.json is missing or has an invalid \'files\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'files\'.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'extra_domains\'.','manifest.json is missing or has an invalid \'build_no\'.'=>'У manifest.json адсутнічае або недапушчальнае поле \'build_no\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'\'server_build_id\' у manifest.json не з\'яўляецца дапушчальным ідэнтыфікатарам зборкі.','manifest.json\'s \'contract\' is not a valid version string.'=>'Параметр \'contract\' у manifest.json не з\'яўляецца дапушчальным радком версіі.','manifest.json\'s \'status\' must be \'published\'.'=>'Параметр \'status\' у manifest.json павінен мець значэнне \'published\'.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Параметр \'kind\' у manifest.json павінен мець значэнне \'plugin\' або \'theme\'.','manifest.json has an invalid \'default_domain_entries\'.'=>'У manifest.json няслушны параметр \'default_domain_entries\'.','manifest.json has an invalid \'default_domain_files\'.'=>'У manifest.json няслушны параметр \'default_domain_files\'.','expected_manifest is missing or has an invalid \'%s\'.'=>'expected_manifest адсутнічае або мае няслушны параметр \'%s\'.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Параметр \'server_build_id\' у expected_manifest не з\'яўляецца дапушчальным ідэнтыфікатарам зборкі.','No record for %s'=>'Няма запісу для %s','One or more served files no longer match the manifest.'=>'Адзін або некалькі файлаў, што выдаюцца, больш не адпавядаюць маніфесту.','No previous build to roll back to.'=>'Няма папярэдняй зборкі для адкату.','The change could not be recorded in the translation index; please try again.'=>'Не атрымалася занесці змяненне ў індэкс перакладаў; паспрабуйце яшчэ раз.','Unknown kind: %s'=>'Невядомы тып: %s','Unsafe domain: %s'=>'Небяспечны дамен: %s','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Тэкставы дамен \'%1$s\' (%2$s) ужо выдаецца для іншага ўсталяванага кампанента (%3$s); нічога не ўсталявана.','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Адкат перазапісаў бы \'%1$s\' (%2$s), які цяпер выдаецца для іншага ўсталяванага кампанента (%3$s); нічога не зменена.','Zip is missing expected file: %s'=>'У zip-архіве адсутнічае чаканы файл: %s','sha256 mismatch for %s'=>'Неадпаведнасць sha256 для %s','The package declares no main translation file.'=>'Пакет не аб\'яўляе асноўнага файла перакладу.','Zip is missing expected default file: %s'=>'У zip-архіве адсутнічае чаканы файл па змаўчанні: %s','sha256 mismatch for default/%s'=>'Неадпаведнасць sha256 для default/%s','Could not stage %s'=>'Не атрымалася падрыхтаваць %s','Could not stage default/%s'=>'Не атрымалася падрыхтаваць default/%s','Entry count mismatch for %s'=>'Неадпаведнасць колькасці запісаў для %s','Could not verify entry count for %s'=>'Не атрымалася праверыць колькасць запісаў для %s','l10n.php entry count mismatch for %s'=>'Неадпаведнасць колькасці запісаў l10n.php для %s','Default supplement entry count mismatch.'=>'Неадпаведнасць колькасці запісаў дапаўнення па змаўчанні.','The package produced no servable main translation file.'=>'Пакет не стварыў прыдатнага для выдачы асноўнага файла перакладу.','Could not prepare %s for rollback.'=>'Не атрымалася падрыхтаваць %s для адкату.','Could not back up %s before replacing it.'=>'Не атрымалася стварыць рэзервовую копію %s перад заменай.','Could not move %s into place.'=>'Не атрымалася перамясціць %s на месца.','Could not read %s back after moving it into place.'=>'Не атрымалася прачытаць %s пасля перамяшчэння на месца.','English (United States)'=>'Англійская (Злучаныя Штаты)','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest недаступны: %s','could not read _manifest.json: %s'=>'не атрымалася прачытаць _manifest.json: %s','failed to parse _manifest.json: %s'=>'не атрымалася разабраць _manifest.json: %s','_manifest.json has an unexpected structure'=>'_manifest.json мае нечаканую структуру','Could not create the package archive.'=>'Не атрымалася стварыць архіў пакета.','No writable temporary directory is available for packaging.'=>'Для пакавання няма даступнага для запісу часовага каталога.','A file in the component could not be read, so it was not packaged.'=>'Файл у кампаненце не ўдалося прачытаць, таму ён не быў запакаваны.','Only plugins and themes can be packaged.'=>'Упакоўваць можна толькі плагіны і тэмы.','The component\'s main file was not found.'=>'Асноўны файл кампанента не знойдзены.','The component is not inside the plugins or themes directory.'=>'Кампанент не знаходзіцца ў каталогу плагінаў або тэм.','Babilim ran out of time for this step and will continue on the next check.'=>'Babilim не паспеў выканаць гэты крок і працягне пры наступнай праверцы.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim не здолеў праверыць гэты сайт, таму нічога не будзе спампавана або ўсталявана, пакуль праверка не завершыцца паспяхова.','Registration response was missing required fields.'=>'У адказе на рэгістрацыю адсутнічалі патрэбныя палі.','No pending challenge to verify.'=>'Няма чакаючага выкліку для праверкі.','Verify response was missing site_token.'=>'У адказе на праверку адсутнічаў site_token.','No site id is on file to rotate a token for.'=>'У файле няма захаванага ідэнтыфікатара сайта, для якога можна змяніць токен.','Rotate-token response was missing site_token.'=>'У адказе на змену токена адсутнічаў site_token.','nonce must be a hexadecimal string.'=>'nonce павінен быць шаснаццатковым радком.','No pending challenge for this nonce.'=>'Для гэтага nonce няма выклікаў у чаканні.','Too many requests.'=>'Занадта шмат запытаў.','The service asked this site to wait before syncing again.'=>'Сэрвіс папрасіў гэты сайт пачакаць перад наступнай сінхранізацыяй.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'На гэтым сайце %1$d кампанентаў на %2$d мовах, што патрабуе %3$d пакетаў праверкі; Babilim можа апрацаваць не больш за %4$d за запуск. Скараціце колькасць кіраваных моў у раздзеле «Налады» або дэактывуйце невыкарыстоўваныя плагіны і тэмы, а потым націсніце «Праверыць яшчэ раз зараз».','Babilim could not finish checking this site.'=>'Babilim не здолеў завяршыць праверку гэтага сайта.','This site\'s address is too long for Babilim to register.'=>'Адрас гэтага сайта занадта доўгі для рэгістрацыі ў Babilim.','This site\'s locale code is not one Babilim can register.'=>'Код лакалі гэтага сайта не можа быць зарэгістраваны ў Babilim.','The download response was missing a usable location.'=>'У адказе на спампоўванне адсутнічала прыдатная лакацыя.','The service\'s upload offer was incomplete.'=>'Прапанова сэрвісу для загрузкі была няпоўнай.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Гэты кампанент большы за дапушчальны для сэрвісу памер, таму яго нельга загрузіць.','The packaged component could not be read.'=>'Не атрымалася прачытаць запакаваны кампанент.','A part of the upload kept failing, so the upload was cancelled.'=>'Адна з частак загрузкі пастаянна завяршалася памылкай, таму загрузку скасавана.','Could not read: %s'=>'Не атрымалася прачытаць: %s']];